package com.dpworld.fms.api;
import com.dpworld.fms.mapimport.*;import com.fasterxml.jackson.databind.ObjectMapper;import java.nio.file.*;import java.security.*;import java.sql.Timestamp;import java.time.Instant;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class RoutingGraphImportService{private final JdbcTemplate jdbc;private final ObjectMapper json;private final Path graphFile,overrideFile;private final Set<String>highways;private final double defaultSpeed;public RoutingGraphImportService(JdbcTemplate jdbc,ObjectMapper json,@Value("${dpwfms.routing.graph-file:}")String graphFile,@Value("${dpwfms.routing.override-file:}")String overrideFile,@Value("${dpwfms.routing.accepted-highway-types:service,unclassified,residential,tertiary,secondary,primary}")String highways,@Value("${dpwfms.routing.default-speed-kph:25}")double defaultSpeed){this.jdbc=jdbc;this.json=json;this.graphFile=graphFile.isBlank()?null:Path.of(graphFile);this.overrideFile=overrideFile.isBlank()?null:Path.of(overrideFile);this.highways=Set.of(highways.split(","));this.defaultSpeed=defaultSpeed;}
 public ImportedRoutingGraph validateConfiguredFiles()throws Exception{if(graphFile==null)throw new IllegalStateException("dpwfms.routing.graph-file is not configured");return new OsmPbfGraphImporter(highways,defaultSpeed).read(graphFile,overrideFile);}
 @Transactional public Map<String,Object>importDraft(String actor)throws Exception{ImportedRoutingGraph graph=validateConfiguredFiles();UUID id=UUID.randomUUID();long version=jdbc.queryForObject("SELECT coalesce(max(version),0)+1 FROM routing_graph_versions",Long.class);jdbc.update("INSERT INTO routing_graph_versions(id,version,name,status,source_file,source_checksum,override_file,override_checksum,source_metadata,import_report,created_by) VALUES (?,?,?,'DRAFT',?,?,?,?,?::jsonb,?::jsonb,?)",id,version,"Imported graph "+version,graphFile.toString(),checksum(graphFile),overrideFile==null?null:overrideFile.toString(),overrideFile==null?null:checksum(overrideFile),json.writeValueAsString(Map.of("acceptedHighways",highways,"defaultSpeedKph",defaultSpeed)),json.writeValueAsString(graph.report()),actor);for(var node:graph.nodes())jdbc.update("INSERT INTO map_nodes(id,code,latitude,longitude,node_type,graph_version_id,osm_node_id,source_kind,tags,approved) VALUES (?,?,?,?,?,?,?,?,?::jsonb,FALSE)",UUID.randomUUID(),node.code(),node.latitude(),node.longitude(),"ROAD",id,node.osmNodeId(),node.sourceKind(),json.writeValueAsString(node.tags()));Map<String,UUID>nodeIds=new HashMap<>();jdbc.query("SELECT id,code FROM map_nodes WHERE graph_version_id=?",rs->{nodeIds.put(rs.getString("code"),rs.getObject("id",UUID.class));},id);for(var segment:graph.segments())jdbc.update("INSERT INTO road_segments(id,code,from_node_id,to_node_id,distance_m,speed_limit_kph,congestion_factor,priority_factor,blocked,restricted,restrictions,graph_version_id,osm_way_id,source_sequence,direction,geometry_wgs84,tags,approved,access_restrictions) VALUES (?,?,?,?,?,?,1,1,?,FALSE,?::jsonb,?,?,?,?,?::jsonb,?::jsonb,FALSE,'{}')",UUID.randomUUID(),segment.code(),nodeIds.get(segment.from()),nodeIds.get(segment.to()),segment.distanceMetres(),segment.speedKph(),segment.blocked(),json.writeValueAsString(Map.of("allowedAssetTypes",segment.allowedAssetTypes())),id,segment.osmWayId(),segment.sequence(),segment.direction(),segment.geometryGeoJson(),json.writeValueAsString(segment.tags()));graph.report().resourceNodes().forEach((resource,node)->{String type=resource.startsWith("PARK")?"PARKING":resource.startsWith("FUEL")?"FUELING":"CHARGING";jdbc.update("INSERT INTO routing_graph_resource_nodes(graph_version_id,resource_type,resource_code,node_code) VALUES (?,?,?,?)",id,type,resource,node);});audit(actor,"ROUTING_GRAPH_IMPORTED",id,Map.of("version",version,"valid",graph.report().valid()));return jdbc.queryForMap("SELECT id,version,status,import_report::text import_report FROM routing_graph_versions WHERE id=?",id);}
 @Transactional public void review(UUID id,String actor,String reason){requireStatus(id,"DRAFT");jdbc.update("UPDATE routing_graph_versions SET reviewed_at=now(),reviewed_by=?,review_reason=?,version_lock=version_lock+1 WHERE id=?",actor,reason,id);audit(actor,"ROUTING_GRAPH_REVIEWED",id,Map.of("reason",reason));}
 @Transactional public void approve(UUID id,String actor,String reason){Map<String,Object>g=requireStatus(id,"DRAFT");if(g.get("reviewed_at")==null)throw new IllegalStateException("graph must be reviewed before approval");if(!String.valueOf(g.get("import_report")).contains("\"valid\":true"))throw new IllegalStateException("invalid import report cannot be approved");jdbc.update("UPDATE routing_graph_versions SET status='APPROVED',approved_at=now(),approved_by=?,review_reason=?,version_lock=version_lock+1 WHERE id=?",actor,reason,id);jdbc.update("UPDATE map_nodes SET approved=TRUE WHERE graph_version_id=?",id);jdbc.update("UPDATE road_segments SET approved=TRUE WHERE graph_version_id=?",id);audit(actor,"ROUTING_GRAPH_APPROVED",id,Map.of("reason",reason));}
 @Transactional public void activate(UUID id,String actor,String reason){requireStatus(id,"APPROVED");jdbc.update("UPDATE routing_graph_versions SET status='RETIRED',version_lock=version_lock+1 WHERE status='ACTIVE'");jdbc.update("UPDATE routing_graph_versions SET status='ACTIVE',activated_at=now(),activated_by=?,review_reason=?,version_lock=version_lock+1 WHERE id=?",actor,reason,id);jdbc.update("UPDATE parking_spaces p SET routing_node_id=n.id FROM routing_graph_resource_nodes r JOIN map_nodes n ON n.graph_version_id=r.graph_version_id AND n.code=r.node_code WHERE r.graph_version_id=? AND r.resource_type='PARKING' AND r.resource_code=p.code",id);jdbc.update("UPDATE service_bays b SET routing_node_id=n.id FROM routing_graph_resource_nodes r JOIN map_nodes n ON n.graph_version_id=r.graph_version_id AND n.code=r.node_code WHERE r.graph_version_id=? AND r.resource_type IN ('CHARGING','FUELING') AND r.resource_code=b.code",id);audit(actor,"ROUTING_GRAPH_ACTIVATED",id,Map.of("reason",reason));}
 private Map<String,Object>requireStatus(UUID id,String status){List<Map<String,Object>>rows=jdbc.queryForList("SELECT *,import_report::text import_report FROM routing_graph_versions WHERE id=? FOR UPDATE",id);if(rows.isEmpty())throw new IllegalArgumentException("unknown routing graph "+id);if(!status.equals(rows.getFirst().get("status")))throw new IllegalStateException("routing graph must be "+status);return rows.getFirst();}private String checksum(Path path)throws Exception{MessageDigest d=MessageDigest.getInstance("SHA-256");try(var input=Files.newInputStream(path)){byte[]b=new byte[8192];for(int n;(n=input.read(b))>0;)d.update(b,0,n);}return HexFormat.of().formatHex(d.digest());}private void audit(String actor,String action,UUID id,Object after){try{jdbc.update("INSERT INTO audit_logs(id,occurred_at,actor,action,resource_type,resource_id,after_value) VALUES (?,now(),?,?,'ROUTING_GRAPH',?,?::jsonb)",UUID.randomUUID(),actor,action,id.toString(),json.writeValueAsString(after));}catch(Exception e){throw new IllegalStateException("cannot audit graph operation",e);}}
}
